pub(crate) fn handle_recover(
    &mut self,
    command: crate::shard::types::RecoverRunCommand,
) -> RuntimeResult<()> {
    let run = command.run;
    let frame = command.frame;
    let artifact_digest = command.artifact_digest;
    let workflow_digest = command.workflow_digest;
    let next_seq = command.next_seq;
    let collect_states = command.collect_states;
    let boundary = command.boundary;

    // Step 1: Load artifact by artifact_digest for verification
    let artifact = self
        .artifact_store
        .load_accepted_artifact(artifact_digest)
        .map_err(|e| match e {
            crate::admission::ArtifactEnvelopeError::ArtifactNotFound { digest } => {
                RuntimeError::Recovery {
                    error: format!("artifact not found during recovery: {digest:?}"),
                }
            }
            other => RuntimeError::Recovery {
                error: format!("artifact load failed: {other}"),
            },
        })?;

    // Step 2: Deserialize and compile workflow from artifact IR
    let parts: vb_core::workflow::WorkflowParts = postcard::from_bytes(&artifact.ir)
        .map_err(|_| RuntimeError::Recovery {
            error: "artifact IR decode failed".to_string(),
        })?;

    let workflow = vb_core::workflow::CompiledWorkflow::try_from_parts(parts)
        .map_err(|e| RuntimeError::Recovery {
            error: format!("workflow compile failed: {e}"),
        })?;

    // Step 3: Verify workflow identity matches command workflow_digest
    if workflow.digest() != workflow_digest {
        return Err(RuntimeError::Recovery {
            error: format!(
                "workflow digest mismatch: expected {workflow_digest:?}, got {:?}",
                workflow.digest()
            ),
        });
    }

    // Step 4: Seed journal sequence from recovered next_seq
    self.seed_journal_sequence(run, next_seq)?;

    // Step 5: Build admission with artifact's required capabilities
    let granted_caps =
        vb_core::capability::CapabilitySet::from_grants(
            artifact.required_capabilities.clone(),
        );
    let admission = self.build_admission(run, workflow.digest(), granted_caps)?;

    // Step 6: Prepare run slots and construct RunState with restored collect_states
    let frame_step_count = frame.step_count();
    let max_slots = workflow.resource_contract().max_slots;
    self.prepare_run_slots(run)?;

    let state = crate::shard::types::RunState {
        frame,
        workflow,
        store: vb_core::value_store::ValueStore::with_max_slots(max_slots),
        action_attempts: crate::shard::helpers::new_action_attempts(frame_step_count),
        admission,
        collect_states,
        action_contracts: Box::new([]),
    };

    self.terminal_runs_remove(run);
    self.admit_run_state(run, state, crate::shard::types::RuntimeState::Initial)?;

    // Step 7: Handle boundary for suspended operations
    match boundary.kind() {
        crate::recovery::RecoveredRunBoundaryKind::None => {}
        crate::recovery::RecoveredRunBoundaryKind::PendingAction => {
            // Re-inject pending action ticket from boundary
            let ticket = boundary
                .pending_action_ticket()
                .map(|t| t.ticket());
            if let Some(t) = ticket {
                self.reinject_pending_action(run, t)?;
            }
        }
        crate::recovery::RecoveredRunBoundaryKind::OpenAsk => {
            // Open ask boundary: resume at ask step, no side effects
        }
    }

    }

    // Step 8: Drive run from recovered state
    match self.drive_run(run) {
        Ok(()) => Ok(()),
        Err(error) => {
            if !self.run_state_contains(run) {
                self.discard_journal_sequence(run);
            }
            Err(error)
        }
    }
}

fn validate_run_exists(&self, run: RunId) -> Result<(), ResumeError> {
    if !self.run_state_contains(run) {
        return Err(ResumeError::RunIdNotFound { run_id: run });
    }
    Ok(())
}

pub struct AcceptedArtifact {
    /// The compiled artifact's content hash (matches `source_digest` when
    /// artifact is produced directly from compilation without separate source).
    pub digest: vb_core::WorkflowDigest,
    /// Digest of the original workflow source that was compiled to produce this artifact.
    /// For directly compiled workflows, this equals `digest`.
    pub source_digest: vb_core::WorkflowDigest,
    /// Digest of the resource/policy contract that governed this artifact's admission.
    /// Derived from the `resource_contract` field of the compiled workflow.
    pub policy_digest: vb_core::WorkflowDigest,
    /// Serialized compiled IR (postcard).
    pub ir: Vec<u8>,
    /// Proof that verification passed.
    pub verification: VerificationProof,
    /// Journal sequence when accepted.
    ///
    /// GAP-007 FIX: This field is currently always set to `EventSeq::new(0)`
    /// because actual sequence tracking is not implemented. The field is retained
    /// as a placeholder for future implementation of proper sequence tracking.
    /// When actual tracking is implemented, replace the placeholder with the real
    /// sequence number from the journal at admission time.
    pub accepted_at_seq: EventSeq,
    /// Required capabilities for actions in this artifact.
    pub required_capabilities: Box<[vb_core::capability::Capability]>,
    /// Validated action contracts bound into this accepted artifact.
    ///
    /// The runtime needs these contracts after crash recovery to validate
    /// action completion size, taint, idempotency, and output-slot authority.
    /// Keeping them inside the accepted artifact makes the artifact the unit of
    /// trust described by the master contract instead of relying on ephemeral
    /// process memory.
    #[serde(default)]
    pub action_contracts: Box<[ActionContract]>,
}

/// Computes the policy digest from a workflow's resource contract.
///
/// GAP-003 FIX: Added per review finding that `AcceptedArtifact` must bind
/// to the policy digest that governed admission. The policy digest is derived
/// from the resource contract by hashing its canonical serialization.
///
/// YAGNI FIX: the serialization buffer is pre-sized to
/// `resource_contract_policy_bytes_bound` (115 bytes) as a single
/// `vec![0u8; bound]` allocation. `postcard::to_slice` honors the slice
/// length it is given, so the Vec must be initialized to its full bound
/// length (not just capacity) before the call. The bound is derived from
/// postcard's per-field upper bounds on `ResourceContract` and is verified
/// by `policy_buffer_fits_canonical_resource_contract` in `admission::tests`.
