pub(crate) fn validate_submit_admission_with_contracts(
    &self,
    run: RunId,
    digest: vb_core::ids::WorkflowDigest,
    caps: CapabilitySet,
    action_contracts: &[vb_core::action::ActionContract],
) -> RuntimeResult<()> {
    // Build admission to validate capabilities
    self.build_admission(run, digest, caps)?;

    // Validate action contracts for duplicates and well-formedness
    // Check for duplicate action IDs
    let mut seen_ids = std::collections::HashSet::new();
    for contract in action_contracts {
        if !seen_ids.insert(contract.id) {
            return Err(RuntimeError::ContractValidationError {
                action: contract.id,
                error: "duplicate action ID".to_string(),
            });
        }
    }

    // Validate each contract individually
    for contract in action_contracts {
        if contract.name.as_str().is_empty() {
            return Err(RuntimeError::ContractValidationError {
                action: contract.id,
                error: "action name is empty".to_string(),
            });
        }
    }

    Ok(())
}
pub fn handle_resume(&mut self, run: RunId) -> Result<ResumeResult, ResumeError> {

    self.validate_run_exists(run)?;
    let current_state = self.get_runtime_state_or_running(run);
    if current_state == RuntimeState::Running {
        return Ok(ResumeResult {
            run_id: run,
            status: ResumeStatus::AlreadyRunning,
            timestamp: current_timestamp(),
        });
    }

fn slot_value_kind(value: &SlotValue) -> vb_core::InputSlotKind {
    match value {
        SlotValue::Null => vb_core::InputSlotKind::Null,
        SlotValue::Bool(_) => vb_core::InputSlotKind::Bool,
        SlotValue::I64(_) => vb_core::InputSlotKind::I64,
        SlotValue::F64(_) => vb_core::InputSlotKind::F64,
        SlotValue::Symbol(_) => vb_core::InputSlotKind::Symbol,
        SlotValue::List(_) => vb_core::InputSlotKind::List,
        SlotValue::Object(_) => vb_core::InputSlotKind::Object,
        SlotValue::Blob(_) => vb_core::InputSlotKind::Blob,
        &_ => vb_core::InputSlotKind::Blob,
    }
}

/// Validates that an action completion matches the expected ticket.
pub fn validate_action_completion(
    state: &crate::shard::types::RunState,
    ticket: ActionTicket,
) -> RuntimeResult<()> {
    validate_ticket_attempt(state, ticket)?;
    if state.frame.step_state(ticket.step) != Ok(StepState::Running) {
        return Err(RuntimeError::InvalidActionCompletion);
    }
    let Some(node) = state.workflow.node(ticket.step) else {
        return Err(RuntimeError::InvalidActionCompletion);
    };
    match node.kind {
        CompiledNodeKind::Do { action, .. } if action == ticket.action => Ok(()),
        _ => Err(RuntimeError::InvalidActionCompletion),
    }
}

}

/// Compact handle-based runtime value stored in numeric slots.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[non_exhaustive]
pub enum SlotValue {
    /// Explicit null value.
    Null,
    /// Boolean scalar.
    Bool(bool),
    /// Signed integer scalar for deterministic arithmetic scaffolding.
    I64(i64),
    /// Finite floating-point scalar.
    F64(FiniteF64),
    /// Interned symbol handle.
    Symbol(SymbolId),
    /// Runtime list arena handle.
    List(ListId),
    /// Runtime object arena handle.
    Object(ObjectId),
    /// Runtime blob arena/storage handle.
    Blob(BlobId),
}

impl Eq for SlotValue {}

impl fmt::Display for SlotValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Null => write!(f, "null"),
            Self::Bool(v) => write!(f, "{v}"),
            Self::I64(v) => write!(f, "{v}"),
            Self::F64(v) => write!(f, "{v}"),
            Self::Symbol(id) => write!(f, "symbol:{}", id.get()),
            Self::List(id) => write!(f, "list:{}", id.get()),
            Self::Object(id) => write!(f, "object:{}", id.get()),
            Self::Blob(id) => write!(f, "blob:{}", id.get()),
        }
    }
}

